B.ad0=new A.ll("intro_4.jpg",1.05,1.18,B.ei,B.ej,B.QF)
B.Sv=new A.a0(B.C,["Kael... est\xe1 me ouvindo? Estou falando com voc\xea pela energia do vazio.","Kael... can you hear me? I'm talking to you through the void energy.","Kael... \xbfme oyes? Te hablo a trav\xe9s de la energ\xeda del vac\xedo."],t.w)
B.acU=new A.dU("nex",B.Sv)
